import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production, this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tid;
    req.userRole = payload.role;
    next();
  } catch (e) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { category, status, sort_by, direction } = req.query;

    // Base query with tenant isolation
    let query = `SELECT id, name, category, status, metadata, created_at 
                 FROM assets WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    // Apply filters
    if (category) {
      query += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }
    if (status) {
      query += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['name', 'created_at', 'category', 'status'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    const sortDir = direction === 'asc' ? 'ASC' : 'DESC';
    query += ` ORDER BY ${sortCol} ${sortDir}`;

    // Pagination
    const limit = Math.min(parseInt(req.query.limit) || 50, 200);
    const offset = parseInt(req.query.offset) || 0;
    query += ` LIMIT ${limit} OFFSET ${offset}`;

    const result = await pool.query(query, params);
    res.json({ data: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/assets/bulk-update', extractTenant, async (req, res) => {
  const { asset_ids, updates } = req.body;
  if (!asset_ids || !Array.isArray(asset_ids) || asset_ids.length === 0) {
    return res.status(400).json({ error: 'asset_ids required' });
  }
  if (asset_ids.length > 100) {
    return res.status(400).json({ error: 'Max 100 assets per batch' });
  }

  try {
    // Build SET clause from updates object
    const allowedFields = ['status', 'category', 'metadata'];
    const setClauses = [];
    const params = [req.tenantId];
    let paramIdx = 2;

    for (const [field, value] of Object.entries(updates || {})) {
      if (allowedFields.includes(field)) {
        setClauses.push(`${field} = $${paramIdx}`);
        params.push(field === 'metadata' ? JSON.stringify(value) : value);
        paramIdx++;
      }
    }

    if (setClauses.length === 0) {
      return res.status(400).json({ error: 'No valid fields to update' });
    }

    // VULNERABILITY: asset_ids are interpolated directly into the query
    const idList = asset_ids.join("','");
    const query = `UPDATE assets SET ${setClauses.join(', ')}, updated_at = NOW() 
                   WHERE tenant_id = $1 AND id IN ('${idList}')`;

    const result = await pool.query(query, params);

    // Audit log
    await pool.query(
      `INSERT INTO audit_log (tenant_id, action, details, performed_by) VALUES ($1, $2, $3, $4)`,
      [req.tenantId, 'bulk_update', JSON.stringify({ asset_ids, updates }), req.userRole]
    );

    res.json({ updated: result.rowCount });
  } catch (err) {
    console.error('Bulk update error:', err.message);
    res.status(500).json({ error: 'Internal error' });
  }
});

app.listen(process.env.PORT || 3000);
